create table if not exists public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.profiles enable row level security;drop policy if exists "profiles_owner_select" on public.profiles;create policy "profiles_owner_select" on public.profiles for select to authenticated using ((select auth.uid())=user_id);create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path=public as $$begin insert into public.profiles(user_id,full_name,email,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.email,new.raw_user_meta_data->>'avatar_url') on conflict(user_id) do update set full_name=excluded.full_name,email=excluded.email,avatar_url=excluded.avatar_url,updated_at=now();return new;end;$$;drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();